528	
529	// recordTerms are the terms no written fixture may hold: the bench passwords,
530	// their Basic encodings, and the external deny list.
531	func recordTerms(o RecordOptions) []string {
532		terms := append([]string(nil), o.DenyTerms...)
533		for _, account := range []struct{ user, password string }{
534			{REDACTED, o.Secrets.AdminPassword},
535			{REDACTED, o.Secrets.PendingAdminPassword},
536			{REDACTED, o.Secrets.PullPassword},
537		} {
538			if account.password == "" {
539				continue
540			}
541			terms = append(terms, account.password,
542				base64.StdEncoding.EncodeToString([]byte(account.user+":"+account.password)))
543		}
544		return terms
545	}
546	
547	// describeLeaks names the rules and the lines of a leak report, never what matched.
548	func describeLeaks(leaks []nexusfixture.Leak) string {
549		parts := make([]string, 0, len(leaks))
550		for _, l := range leaks {
551			parts = append(parts, fmt.Sprintf("%s at line %d", l.Rule, l.Line))
552		}
553		return strings.Join(parts, ", ")
554	}
555	
556	// holdsTerm searches the raw answer, whatever the redaction would drop or hide
557	// (a header outside the allowlist, an HTML body), for a term in the forms it can
558	// take: as is, in another case, URL-escaped, JSON-escaped.
559	func holdsTerm(header http.Header, body []byte, terms []string) bool {
560		var raw strings.Builder
561		for name, values := range header {
562			raw.WriteString(name + ": " + strings.Join(values, "\n") + "\n")
563		}
564		raw.Write(body)
565		text := strings.ToLower(raw.String())
566		jsonEscaper := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
567		for _, term := range terms {
568			if term == "" {
569				continue
570			}
571			for _, v := range []string{term, url.QueryEscape(term), url.PathEscape(term), jsonEscaper.Replace(term)} {
572				if strings.Contains(text, strings.ToLower(v)) {
573					return true
574				}
575			}
576		}
577		return false
578	}
