193	// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
194	// folder name of fsys, or every folder of fsys.
195	func recordCampaigns(fsys fs.FS, wanted []string) ([]string, error) {
196		if len(wanted) == 0 {
197			entries, err := fs.ReadDir(fsys, ".")
198			if err != nil {
199				return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
200			}
201			var all []string
202			for _, e := range entries {
203				if e.IsDir() && !strings.HasPrefix(e.Name(), ".") {
204					all = append(all, e.Name())
205				}
206			}
207			return all, nil
208		}
209		for _, c := range wanted {
210			if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
211				return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
212			}
213			if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
214				return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
215			}
216		}
217		return wanted, nil
218	}
