419	
420	// gatherAnswers asks every job and returns the files to write and the fixtures
421	// that did not change. The first problem ends the run: nothing is written yet.
422	func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged []string, err error) {
423		clients := map[string]*client{}
424		defer func() {
425			for _, c := range clients {
426				c.closeIdle()
427			}
428		}()
429		now := time.Now
430		if o.Now != nil {
431			now = o.Now
432		}
433		date := now().Format(recordedDateLayout)
434		for _, j := range jobs {
435			key := j.origin + "\x00" + j.user
436			c, ok := clients[key]
437			if !ok {
438				c = newClient(j.origin, j.user, j.password)
439				clients[key] = c
440			}
441			data, same, err := j.record(ctx, o, c, date)
442			switch {
443			case err != nil:
444				return nil, nil, err
445			case same:
446				unchanged = append(unchanged, j.name)
447			default:
448				writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
449			}
450		}
451		return writes, unchanged, nil
452	}
