512	var serverHeader = regexp.MustCompile(`^Nexus/(\S+) \(([A-Za-z]+)\)$`)
513	
514	// benchVersionMatches reports whether a Server header names the version and the
515	// edition of the descriptor.
516	func benchVersionMatches(server string, d Descriptor) bool {
517		m := serverHeader.FindStringSubmatch(server)
518		return m != nil && m[1] == d.NexusVersion && m[2] == d.Edition
519	}
