547	// describeLeaks names the rules and the lines of a leak report, never what matched.
548	func describeLeaks(leaks []nexusfixture.Leak) string {
549		parts := make([]string, 0, len(leaks))
550		for _, l := range leaks {
551			parts = append(parts, fmt.Sprintf("%s at line %d", l.Rule, l.Line))
552		}
553		return strings.Join(parts, ", ")
554	}
