92	// CheckLeaks scans one fixture, line by line (lines count from 1), for what a
93	// fixture must not hold: an Authorization other than the placeholders, a cookie
94	// or session header, a request header outside Host, Authorization and Accept, a
95	// response header outside ResponseHeaderAllowlist, a line of a header section
96	// that is not "Name: value", a request query parameter other than n and last, a
97	// JWT-like value or another well-known secret format, a JSON secret key whose
98	// value is not "<redacted>" (or null), a host outside AllowedHosts, a private,
99	// link-local, CGNAT or unique-local address, an internal name or local path, and
100	// each term of exact (recorder passwords and their Basic encodings, or an
101	// external deny list), also in another case, JSON-escaped or URL-escaped; an
102	// empty term matches nothing. The text is scanned as written, not parsed: a file
103	// that does not parse is still checked.
104	func CheckLeaks(fixture string, data []byte, exact []string) []Leak {
105		c := &leakScan{fixture: fixture, seen: map[leakKey]bool{}, exact: exactVariants(exact)}
106		text := string(data)
107		state := stMeta
108		for i, line := range strings.Split(text, "\n") {
109			state = c.scanLine(i+1, line, state)
110		}
111		c.scanJSONSecrets(text)
112		sort.SliceStable(c.leaks, func(i, j int) bool { return c.leaks[i].Line < c.leaks[j].Line })
113		return c.leaks
114	}
