204	func (c *leakScan) scanHeader(n int, line string, state lineState) {
205		if line == "" {
206			return
207		}
208		name, value, ok := strings.Cut(line, ":")
209		name, value = strings.TrimSpace(name), strings.TrimSpace(value)
210		if !ok || name == "" {
211			c.add(n, ruleMalformed)
212			return
213		}
214		lower := strings.ToLower(name)
215		switch {
216		case lower == "authorization" && value != authBasicRedacted && value != authBearerRedacted:
217			c.add(n, ruleAuthorization)
218		case contains(sessionHeaders, lower):
219			c.add(n, ruleSession)
220		}
221		if state == stRespHeaders && !allowedResponseHeader(name) {
222			c.add(n, ruleHeaderAllowed)
223		}
224		if state == stReqHeaders && !allowedRequestHeader(name) {
225			c.add(n, ruleRequestHeader)
226		}
227		if state == stReqHeaders && lower == "host" && !allowedHost(value) {
228			c.add(n, ruleHost)
229		}
