257	// writeFileAtomic writes data to path through a temporary file of the same
258	// folder and a rename, so a reader sees the old file or the new one, never a
259	// partial one. Missing folders are created with dirMode. The temporary file is
260	// removed when anything fails. The error text holds paths, never data.
261	func writeFileAtomic(path string, data []byte, fileMode, dirMode os.FileMode) (err error) {
262		dir := filepath.Dir(path)
263		if err := os.MkdirAll(dir, dirMode); err != nil {
264			return fmt.Errorf("create the folder %s: %w", dir, err)
265		}
266		tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*.tmp")
267		if err != nil {
268			return fmt.Errorf("create a temporary file in %s: %w", dir, err)
269		}
270		defer func() {
271			if err != nil {
272				_ = tmp.Close()
273				_ = os.Remove(tmp.Name())
274			}
275		}()
276		if _, err = tmp.Write(data); err != nil {
277			return fmt.Errorf("write %s: %w", tmp.Name(), err)
278		}
279		if err = tmp.Chmod(fileMode); err != nil {
280			return fmt.Errorf("set the mode of %s: %w", tmp.Name(), err)
281		}
282		if err = tmp.Sync(); err != nil {
283			return fmt.Errorf("sync %s: %w", tmp.Name(), err)
284		}
285		if err = tmp.Close(); err != nil {
286			return fmt.Errorf("close %s: %w", tmp.Name(), err)
287		}
288		if err = os.Rename(tmp.Name(), path); err != nil {
289			return fmt.Errorf("replace %s: %w", path, err)
290		}
291		syncDir(dir)
292		return nil
293	}
294	
295	// syncDir flushes the folder entry written by the rename. Syncing the file
296	// alone does not make the new name durable: after a power cut the folder could
297	// still list the old file, and a password written just before it was sent to
298	// Nexus would be lost. It is best effort: Windows cannot open a folder for
299	// syncing and some file systems do not support it, and the file is already
300	// replaced either way, so every error is ignored.
301	func syncDir(dir string) {
302		d, err := os.Open(dir)
303		if err != nil {
304			return
305		}
306		_ = d.Sync()
307		_ = d.Close()
308	}
